script:
(function () {
  'use strict';
  // Motorcycle, RV or boat: loan payment plus the full cost of owning it for the years you keep it.
  //   Loan = price - down - trade-in + owed (+ sales tax and fees when financed), >= 0.
  //   Payment M = L x i / (1 - (1 + i)^-n), i = APR / 12 (M = L / n at 0%); monthly amortization.
  //   Value after y years = price x (1 - d)^y (declining balance at the yearly depreciation rate d).
  //   Cost of ownership over H years = (price - value after H) + interest paid in H years + sales tax
  //     + fees + running costs (insurance + storage + maintenance + per-day costs x days used) x H.
  //     This equals cash paid out (down, trade-in equity, payments, payoff at sale) minus the sale value.
  //   Cost per day of use = cost of ownership / (days used per year x H).
  // Vehicle-type presets (term, depreciation, yearly costs, days of use) are rough starting points
  //   for illustration, not market data; every one can be edited.
  // Verified in Node (scratchpad tests/autogroup/mv.test.js): $25,000 at 6% for 60 months = $483.32/mo;
  //   $100,000 at 7% for 180 months = $898.83/mo (published closed-form value); the balance after 60
  //   payments matches the closed-form remaining balance L(1+i)^k - M((1+i)^k - 1)/i; the cost of
  //   ownership equals the cash-flow total (down + payments + payoff - sale value); at 0% and with 0 days
  //   of use no NaN or Infinity reaches the page; blank and negative inputs show an error.
  var PRESETS = {
    motorcycle: { term: 60, dep: 12, ins: 600, storage: 0, maint: 500, perDay: 15, days: 60 },
    motorhome: { term: 180, dep: 9, ins: 1500, storage: 1800, maint: 2000, perDay: 120, days: 30 },
    trailer: { term: 144, dep: 9, ins: 500, storage: 1200, maint: 700, perDay: 60, days: 25 },
    boat: { term: 144, dep: 8, ins: 800, storage: 1500, maint: 1500, perDay: 80, days: 25 }
  };
  var FIELDS = { term: 'mvTerm', dep: 'mvDep', ins: 'mvIns', storage: 'mvStorage', maint: 'mvMaint', perDay: 'mvPerDay', days: 'mvDays' };
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function signed(v) { return (v < -0.005 ? '−' : '') + money.format(Math.abs(v)); }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  function project(o) {
    var taxable = Math.max(0, o.price - (o.tradeCredit ? o.trade : 0));
    var tax = taxable * o.taxRate / 100;
    var loan = Math.max(0, o.price - o.down - o.trade + o.owed + (o.finance ? tax + o.fees : 0));
    var i = o.apr / 1200, pmt = monthlyPayment(loan, o.apr / 100, o.months);
    var running = o.ins + o.storage + o.maint + o.perDay * o.days;
    var bal = loan, rows = [], value = o.price, interestH = 0, paidH = 0, totalInterest = 0;
    var horizon = Math.max(o.years * 12, o.months);
    for (var m = 1; m <= horizon; m++) {
      var pay = 0, interest = 0;
      if (bal > 0.005) {
        interest = bal * i;
        pay = Math.min(pmt, bal + interest);
        if (m === o.months) pay = bal + interest;
        bal = Math.max(0, bal + interest - pay);
      }
      totalInterest += interest;
      if (m <= o.years * 12) {
        interestH += interest; paidH += pay;
        var y = Math.ceil(m / 12);
        if (!rows[y - 1]) rows[y - 1] = { year: y, paid: 0, interest: 0 };
        rows[y - 1].paid += pay; rows[y - 1].interest += interest;
        if (m % 12 === 0) {
          var newValue = o.price * Math.pow(1 - o.dep / 100, y);
          rows[y - 1].dep = value - newValue;
          value = newValue;
          rows[y - 1].value = value;
          rows[y - 1].balance = bal;
        }
      }
    }
    var balH = rows[o.years - 1].balance;
    var depTotal = o.price - value;
    var total = depTotal + interestH + tax + o.fees + running * o.years;
    return { tax: tax, loan: loan, pmt: pmt, totalInterest: totalInterest, running: running, rows: rows, value: value,
             balH: balH, interestH: interestH, paidH: paidH, depTotal: depTotal, total: total,
             perYear: total / o.years, perDay: o.days > 0 ? total / (o.days * o.years) : NaN,
             upfront: o.down + (o.finance ? 0 : tax + o.fees) };
  }

  function applyPreset() {
    var p = PRESETS[el('mvType').value];
    if (!p) return;
    Object.keys(FIELDS).forEach(function (k) { el(FIELDS[k]).value = String(p[k]); });
  }

  function clearResults() {
    ['mvPayment', 'mvPerYear', 'mvCostPerDay', 'mvTotalInterest', 'mvLoanOut', 'mvValue', 'mvBalance', 'mvEquity', 'mvDepOut',
     'mvInterestH', 'mvTaxFees', 'mvRunning', 'mvTotal'].forEach(function (id) { setText(id, '–'); });
    el('mvUnderwater').hidden = true;
    el('mvSchedule').innerHTML = '';
  }

  function update() {
    var o = {
      price: read('mvPrice'), down: read('mvDown', true), apr: read('mvApr'), months: read('mvTerm'),
      taxRate: read('mvTaxRate', true), fees: read('mvFees', true), years: read('mvYears'), days: read('mvDays', true),
      ins: read('mvIns', true), storage: read('mvStorage', true), maint: read('mvMaint', true), perDay: read('mvPerDay', true),
      dep: read('mvDep', true), trade: read('mvTrade', true), owed: read('mvOwed', true),
      finance: el('mvFinanceCosts').checked, tradeCredit: el('mvTradeCredit').checked
    };
    var error = el('mvError'), msg = '';
    if (isNaN(o.price) || o.price <= 0) msg = 'Enter a purchase price greater than $0.';
    else if (isNaN(o.apr) || o.apr < 0 || o.apr > 40) msg = 'Enter an interest rate from 0% to 40%.';
    else if (isNaN(o.months) || o.months < 12 || o.months > 240 || o.months % 1 !== 0) msg = 'Enter a loan term of 12 to 240 whole months.';
    else if (isNaN(o.years) || o.years < 1 || o.years > 30 || o.years % 1 !== 0) msg = 'Enter 1 to 30 whole years of ownership.';
    else if ([o.down, o.taxRate, o.fees, o.days, o.ins, o.storage, o.maint, o.perDay, o.dep, o.trade, o.owed].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Amounts and rates cannot be negative.';
    else if (o.taxRate > 20) msg = 'Enter a sales tax rate of 20% or less.';
    else if (o.dep >= 100) msg = 'Enter a yearly drop in value below 100%.';
    else if (o.days > 366) msg = 'Enter at most 366 days of use a year.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var r = project(o);
    setText('mvPayment', r.loan > 0.005 ? money.format(r.pmt) : '$0.00');
    setText('mvPerYear', money.format(r.perYear));
    setText('mvCostPerDay', isNaN(r.perDay) ? 'No days entered' : money.format(r.perDay));
    setText('mvTotalInterest', money.format(r.totalInterest));
    setText('mvLoanOut', money.format(r.loan));
    setText('mvValue', money.format(r.value));
    setText('mvBalance', money.format(r.balH));
    setText('mvEquity', signed(r.value - r.balH));
    setText('mvDepOut', money.format(r.depTotal));
    setText('mvInterestH', money.format(r.interestH));
    setText('mvTaxFees', money.format(r.tax + o.fees));
    setText('mvRunning', money.format(r.running * o.years));
    setText('mvTotal', money.format(r.total));
    setText('mvYearsLabel', String(o.years));
    var under = r.balH - r.value;
    el('mvUnderwater').hidden = !(under > 0.5);
    setText('mvUnderAmount', money.format(Math.max(0, under)));

    var body = el('mvSchedule');
    body.innerHTML = r.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money0.format(row.paid) + '</td><td>' + money0.format(row.interest) + '</td><td>' +
        money0.format(r.running) + '</td><td>' + money0.format(row.dep) + '</td><td>' + money0.format(row.balance) + '</td><td>' +
        money0.format(row.value) + '</td><td>' + (row.value - row.balance < -0.5 ? '−' : '') + money0.format(Math.abs(row.value - row.balance)) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('mvForm');
    if (!form) return;
    el('mvType').addEventListener('change', applyPreset);
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
